:root {
    --color-bg-primary: #0a0e27;
    --color-bg-secondary: #16213e;
    --color-bg-tertiary: #1a2a4a;
    --color-text-primary: #f5f5f5;
    --color-text-secondary: #b0b0b0;
    --color-accent: #d4af37;
    --color-accent-light: #e8c547;
    --color-danger: #ff4757;
    --color-success: #2ed573;
    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 1.5rem;
    --spacing-lg: 2rem;
    --spacing-xl: 3rem;
    --spacing-2xl: 4rem;
    --border-radius: 8px;
    --border-radius-lg: 12px;
    --transition: all 0.3s ease;
}

/* Reset */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
        'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
        sans-serif;
    background-color: var(--color-bg-primary);
    color: var(--color-text-primary);
    line-height: 1.6;
    overflow-x: hidden;
}

/* Utility Classes */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-lg);
}

.section {
    padding: var(--spacing-2xl) 0;
    border-bottom: 1px solid var(--color-bg-tertiary);
}

.section-title {
    font-size: 2.5rem;
    font-weight: 600;
    margin-bottom: var(--spacing-xl);
    text-align: center;
    color: var(--color-text-primary);
    letter-spacing: -0.5px;
}

/* Button Styles */
.btn {
    display: inline-block;
    padding: var(--spacing-sm) var(--spacing-lg);
    border: none;
    border-radius: var(--border-radius);
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition);
    text-decoration: none;
    text-align: center;
    min-width: 150px;
}

.btn-primary {
    background-color: var(--color-accent);
    color: var(--color-bg-primary);
}

.btn-primary:hover {
    background-color: var(--color-accent-light);
    transform: translateY(-2px);
    box-shadow: 0 8px 16px rgba(212, 175, 55, 0.3);
}

.btn-secondary {
    background-color: rgba(212, 175, 55, 0.2);
    color: var(--color-accent);
    border: 1px solid var(--color-accent);
}

.btn-secondary:hover {
    background-color: rgba(212, 175, 55, 0.3);
    transform: translateY(-2px);
}

.btn-icon {
    background: none;
    border: none;
    font-size: 1.5rem;
    cursor: pointer;
    transition: var(--transition);
    padding: var(--spacing-xs);
}

.btn-icon:hover {
    transform: scale(1.1);
}

.icon-button {
    background: none;
    border: none;
    font-size: 1.25rem;
    cursor: pointer;
    color: var(--color-text-primary);
    padding: var(--spacing-xs);
    transition: var(--transition);
    margin-left: var(--spacing-sm);
}

.icon-button:hover {
    color: var(--color-accent);
    transform: scale(1.1);
}

/* Header */
.header {
    background-color: var(--color-bg-secondary);
    padding: var(--spacing-md) 0;
    border-bottom: 1px solid var(--color-bg-tertiary);
    position: sticky;
    top: 0;
    z-index: 100;
    backdrop-filter: blur(10px);
    background-color: rgba(22, 33, 62, 0.9);
}

.header-content {
    display: flex;
    align-items: center;
    justify-content: space-between;
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-lg);
}

.logo {
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: 2px;
    color: var(--color-accent);
    text-transform: uppercase;
}

.nav {
    display: flex;
    gap: var(--spacing-lg);
    flex: 1;
    justify-content: center;
}

.nav-link {
    color: var(--color-text-primary);
    text-decoration: none;
    font-weight: 500;
    font-size: 0.95rem;
    transition: var(--transition);
    position: relative;
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: -4px;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--color-accent);
    transition: var(--transition);
}

.nav-link:hover {
    color: var(--color-accent);
}

.nav-link:hover::after {
    width: 100%;
}

.header-actions {
    display: flex;
    gap: var(--spacing-sm);
}

/* Hero Section */
.hero {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-2xl);
    align-items: center;
    padding: var(--spacing-2xl) 0;
    background: linear-gradient(135deg, var(--color-bg-secondary) 0%, var(--color-bg-tertiary) 100%);
    min-height: 500px;
}

.hero-content {
    padding: var(--spacing-lg);
}

.hero-title {
    font-size: 3.5rem;
    font-weight: 700;
    margin-bottom: var(--spacing-md);
    line-height: 1.2;
    background: linear-gradient(135deg, var(--color-accent), var(--color-text-primary));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.hero-subtitle {
    font-size: 1.25rem;
    color: var(--color-text-secondary);
    margin-bottom: var(--spacing-xl);
    max-width: 400px;
}

.hero-image {
    display: flex;
    align-items: center;
    justify-content: center;
}

.placeholder-image {
    width: 100%;
    aspect-ratio: 1;
    background: linear-gradient(135deg, var(--color-bg-tertiary), var(--color-accent-light));
    border-radius: var(--border-radius-lg);
    opacity: 0.3;
}

/* Products Grid */
.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: var(--spacing-lg);
}

.product-card {
    background-color: var(--color-bg-secondary);
    border-radius: var(--border-radius-lg);
    overflow: hidden;
    transition: var(--transition);
    border: 1px solid var(--color-bg-tertiary);
}

.product-card:hover {
    transform: translateY(-8px);
    border-color: var(--color-accent);
    box-shadow: 0 20px 40px rgba(212, 175, 55, 0.15);
}

.product-image {
    position: relative;
    width: 100%;
    aspect-ratio: 1;
    overflow: hidden;
    background-color: var(--color-bg-tertiary);
}

.placeholder-product {
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, var(--color-bg-tertiary), var(--color-accent-light));
    opacity: 0.2;
}

.badge {
    position: absolute;
    top: var(--spacing-md);
    right: var(--spacing-md);
    padding: var(--spacing-xs) var(--spacing-sm);
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.badge.new {
    background-color: var(--color-success);
    color: var(--color-bg-primary);
}

.badge.hot {
    background-color: var(--color-danger);
    color: white;
}

.badge.trending {
    background-color: var(--color-accent);
    color: var(--color-bg-primary);
}

.product-info {
    padding: var(--spacing-md);
}

.product-name {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: var(--spacing-xs);
    color: var(--color-text-primary);
}

.product-category {
    font-size: 0.85rem;
    color: var(--color-text-secondary);
    margin-bottom: var(--spacing-sm);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.product-rating {
    font-size: 0.9rem;
    color: var(--color-text-secondary);
    margin-bottom: var(--spacing-md);
}

.product-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.price {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--color-accent);
}

/* Deals Section */
.deals-section {
    background-color: var(--color-bg-secondary);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-lg);
}

.deal-card {
    position: relative;
    border-radius: var(--border-radius-lg);
    overflow: hidden;
    height: 300px;
    transition: var(--transition);
    border: 1px solid var(--color-bg-tertiary);
}

.deal-card-large {
    grid-column: span 2;
}

@media (max-width: 900px) {
    .deal-card-large {
        grid-column: span 1;
    }
}

.deal-card:hover {
    transform: scale(1.02);
}

.deal-image {
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, var(--color-accent-light), var(--color-bg-tertiary));
    opacity: 0.2;
}

.deal-overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(135deg, rgba(0, 0, 0, 0.6), rgba(0, 0, 0, 0.3));
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    padding: var(--spacing-lg);
    text-align: center;
    transition: var(--transition);
}

.deal-card:hover .deal-overlay {
    background: linear-gradient(135deg, rgba(0, 0, 0, 0.7), rgba(0, 0, 0, 0.4));
}

.deal-content {
    z-index: 2;
}

.deal-badge {
    display: inline-block;
    background-color: var(--color-danger);
    color: white;
    padding: var(--spacing-xs) var(--spacing-sm);
    border-radius: 4px;
    font-size: 0.85rem;
    font-weight: 700;
    margin-bottom: var(--spacing-md);
    text-transform: uppercase;
    letter-spacing: 1px;
}

.deal-title {
    font-size: 1.75rem;
    font-weight: 700;
    margin-bottom: var(--spacing-sm);
    color: var(--color-text-primary);
}

.deal-description {
    font-size: 0.95rem;
    color: var(--color-text-secondary);
    margin-bottom: var(--spacing-md);
}

.deal-countdown {
    font-size: 0.9rem;
    color: var(--color-accent);
    font-weight: 600;
}

/* Editorial Section */
.editorial-section {
    background-color: var(--color-bg-primary);
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-lg);
}

.editorial-card {
    background-color: var(--color-bg-secondary);
    border-radius: var(--border-radius-lg);
    overflow: hidden;
    transition: var(--transition);
    border: 1px solid var(--color-bg-tertiary);
    display: flex;
    flex-direction: column;
    height: 100%;
}

.editorial-card.featured {
    grid-column: span 2;
}

@media (max-width: 900px) {
    .editorial-card.featured {
        grid-column: span 1;
    }
}

.editorial-card:hover {
    transform: translateY(-8px);
    border-color: var(--color-accent);
    box-shadow: 0 20px 40px rgba(212, 175, 55, 0.15);
}

.editorial-image {
    width: 100%;
    aspect-ratio: 16/9;
    background-color: var(--color-bg-tertiary);
    overflow: hidden;
}

.placeholder-image {
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, var(--color-bg-tertiary), var(--color-accent-light));
    opacity: 0.2;
}

.editorial-content {
    padding: var(--spacing-lg);
    flex: 1;
    display: flex;
    flex-direction: column;
}

.editorial-category {
    display: inline-block;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--color-accent);
    font-weight: 600;
    margin-bottom: var(--spacing-sm);
}

.editorial-title {
    font-size: 1.3rem;
    font-weight: 700;
    margin-bottom: var(--spacing-sm);
    line-height: 1.3;
    color: var(--color-text-primary);
}

.editorial-excerpt {
    font-size: 0.95rem;
    color: var(--color-text-secondary);
    margin-bottom: var(--spacing-md);
    flex: 1;
}

.editorial-meta {
    display: flex;
    justify-content: space-between;
    font-size: 0.85rem;
    color: var(--color-text-secondary);
    border-top: 1px solid var(--color-bg-tertiary);
    padding-top: var(--spacing-md);
}

.editorial-author {
    font-weight: 600;
}

.editorial-date {
    color: var(--color-text-secondary);
}

/* Newsletter Section */
.newsletter-section {
    background: linear-gradient(135deg, var(--color-bg-secondary), var(--color-bg-tertiary));
    padding: var(--spacing-2xl) 0;
    border: 1px solid var(--color-bg-tertiary);
}

.newsletter-content {
    text-align: center;
    max-width: 600px;
    margin: 0 auto;
}

.newsletter-title {
    font-size: 2rem;
    font-weight: 700;
    margin-bottom: var(--spacing-sm);
    color: var(--color-text-primary);
}

.newsletter-subtitle {
    font-size: 1rem;
